{"path":"services.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Offerings — {{BUSINESS_NAME}}</title>
  <style>
    :root{--accent:#6b8a6f;--muted:#6c6f72;--bg:#fbfbfa;--card:#ffffff;--glass:rgba(255,255,255,0.6)}
    html,body{height:100%;margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial; background:var(--bg);color:#111}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px;background:linear-gradient(180deg,rgba(255,255,255,0.6),transparent);backdrop-filter:blur(6px);position:sticky;top:0;z-index:10}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:44px;height:44px;background:var(--accent);border-radius:8px;display:grid;place-items:center;color:white;font-weight:700}
    nav a{margin-left:18px;text-decoration:none;color:var(--muted);font-weight:600}
    main{max-width:1100px;margin:28px auto;padding:28px}
    .hero{display:grid;grid-template-columns:1fr 340px;gap:28px;align-items:start}
    .heroCard{background:linear-gradient(180deg,rgba(255,255,255,0.9),var(--glass));padding:26px;border-radius:12px;box-shadow:0 6px 18px rgba(24,24,24,0.06)}
    .kicker{font-size:13px;color:var(--accent);font-weight:700}
    h1{margin:8px 0 4px;font-size:28px}
    p.lead{color:var(--muted);margin:0 0 12px}
    .pill{display:inline-block;padding:6px 10px;background:#f2f6f2;border-radius:999px;font-weight:700;color:var(--accent);font-size:13px}
    .methods{display:flex;flex-direction:column;gap:12px;margin-top:10px}
    .method{display:flex;align-items:center;gap:12px;padding:12px;border-radius:10px;background:#fff;border:1px solid #eef2ed}
    .method svg{width:44px;height:44px;border-radius:8px;flex-shrink:0}
    .muted{color:var(--muted);font-size:14px}

    /* Pricing comparator */
    .comparator{background:#fff;padding:16px;border-radius:10px;border:1px solid #eef2ed;margin-top:18px}
    .toggle{display:inline-flex;border-radius:999px;padding:4px;background:#f0f3f0;border:1px solid #e8ede9}
    .toggle button{border:0;background:transparent;padding:6px 12px;border-radius:999px;font-weight:700;color:var(--muted);cursor:pointer}
    .toggle button.active{background:linear-gradient(90deg,var(--accent),#4f6f54);color:white}
    .priceRow{display:flex;justify-content:space-between;align-items:center;margin-top:12px}
    .priceValue{font-size:22px;font-weight:800}
    .small{font-size:13px;color:var(--muted)}

    /* Mood selector */
    .moodWrap{margin-top:18px;background:#fff;padding:16px;border-radius:10px;border:1px solid #eef2ed}
    .moods{display:flex;gap:8px;flex-wrap:wrap}
    .moodBtn{padding:8px 12px;border-radius:999px;background:#f7faf6;border:1px solid #e6efe6;cursor:pointer}
    .moodBtn.selected{background:var(--accent);color:white;border-color:transparent}
    .recommend{margin-top:12px;padding:14px;border-radius:10px;background:linear-gradient(180deg,#ffffff,#fbfff9);border:1px dashed #e4efe3}
    .cta{display:inline-block;margin-top:12px;padding:12px 16px;border-radius:10px;background:var(--accent);color:#fff;text-decoration:none;font-weight:700}

    /* FAQ */
    .faq{margin-top:22px}
    .qa{background:#fff;padding:12px;border-radius:10px;border:1px solid #eef2ed;margin-bottom:8px}

    footer{margin:48px 0 80px;color:var(--muted);font-size:13px;text-align:center}

    @media(max-width:860px){.hero{grid-template-columns:1fr}.heroCard{order:2}}

  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">A</div>
      <div>
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Blends</a>
      <a href="shop.html">Shop</a>
      <a href="pricing.html">Investment</a>
      <a href="about.html">About</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <div class="heroCard">
        <div class="kicker">Consultations & Sessions</div>
        <h1>Thoughtful scent pathways that may support emotional ease</h1>
        <p class="lead">Tailored scent sessions — single consults or a concentrated VIP Day — designed to help you craft small practices that may support steadier moments. Safety-forward, with dilution and patch-test guidance.</p>

        <div class="pill">Most clients choose a focused series</div>

        <div class="moodWrap">
          <strong>How are you right now?</strong>
          <div class="moods" role="list">
            <button class="moodBtn" data-key="stressed">Stressed</button>
            <button class="moodBtn" data-key="sleep">Sleepy</button>
            <button class="moodBtn" data-key="fog">Foggy</button>
            <button class="moodBtn" data-key="lifted">Low energy</button>
            <button class="moodBtn" data-key="celebrate">Celebratory</button>
          </div>

          <div class="recommend" id="recommend">
            <div style="font-weight:700">Recommended approach</div>
            <div id="recommendText" class="muted">Choose how you feel to see a recommended session and a suggested scent approach.</div>
            <a id="moodCTA" class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          </div>
        </div>

      </div>

      <aside class="heroCard">
        <div style="font-size:13px;color:var(--muted);font-weight:700">Pricing view</div>
        <div class="comparator">
          <div style="display:flex;justify-content:space-between;align-items:center">
            <div class="small">Show prices as</div>
            <div class="toggle" role="tablist">
              <button id="monthlyBtn" class="active">Single</button>
              <button id="packageBtn">Series</button>
            </div>
          </div>

          <div class="priceRow" style="margin-top:14px">
            <div>
              <div class="small">Intro Consult</div>
              <div class="priceValue" data-monthly="95" data-package="250">$95</div>
            </div>
            <div class="small">45 minutes</div>
          </div>

          <div class="priceRow">
            <div>
              <div class="small">Focused Session</div>
              <div class="priceValue" data-monthly="150" data-package="420">$150</div>
            </div>
            <div class="small">60 minutes</div>
          </div>

          <div class="priceRow">
            <div>
              <div class="small">VIP Day</div>
              <div class="priceValue" data-monthly="750" data-package="2100">$750</div>
            </div>
            <div class="small">Full day + custom blends</div>
          </div>

        </div>

        <div style="margin-top:12px;text-align:center">
          <a id="bookNow" class="cta" href="{{PRIMARY_CTA_URL}}">Book a time</a>
        </div>
      </aside>
    </section>

    <section class="whatToExpect" style="margin-top:26px">
      <h2 style="margin:0 0 12px">What to expect</h2>
      <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:14px">
        <div class="method">
          <svg viewBox="0 0 24 24" fill="none"><rect width="24" height="24" rx="6" fill="#eaf6ee"></rect><path d="M7 13c1.5-2 3-3 5-3s3.5 1 5 3" stroke="#4f6f54" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>
          <div>
            <div style="font-weight:700">Guided consult</div>
            <div class="muted">A close listening session with a practical scent plan that may support your daily rhythm.</div>
          </div>
        </div>
        <div class="method">
          <svg viewBox="0 0 24 24" fill="none"><rect width="24" height="24" rx="6" fill="#fff4e8"></rect><path d="M12 7v10M7 12h10" stroke="#a66b36" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>
          <div>
            <div style="font-weight:700">Practical blends</div>
            <div class="muted">Blends you can use at home, travel-safe dilutions and usage notes.</div>
          </div>
        </div>
        <div class="method">
          <svg viewBox="0 0 24 24" fill="none"><rect width="24" height="24" rx="6" fill="#eef7ff"></rect><path d="M8 15l2-4 4 4" stroke="#2b6fb6" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>
          <div>
            <div style="font-weight:700">Short practices</div>
            <div class="muted">Simple scent-based micro-practices to integrate into a busy day.</div>
          </div>
        </div>
      </div>
    </section>

    <section class="faq">
      <h3 style="margin-top:22px">Questions & safety notes</h3>
      <div class="qa">
        <strong>Are these medical treatments?</strong>
        <div class="muted">No. Sessions and blends are wellness-focused and may support emotional or sensory balance. They are not medical advice.</div>
      </div>
      <div class="qa">
        <strong>Patch testing & dilution</strong>
        <div class="muted">All personalized blends include dilution ratios and a recommended patch-test protocol. If you are prone to sensitivities, always test on a small skin area and wait 24 hours.</div>
      </div>
      <div class="qa">
        <strong>Pregnancy, pets & safety</strong>
        <div class="muted">Certain essential oils are best avoided during pregnancy and around some pets. We will review contraindications as part of the intake and tailor recommendations accordingly.</div>
      </div>
      <div class="qa">
        <strong>Cancellation & rescheduling</strong>
        <div class="muted">Please see our booking page for terms. We make space for thoughtful scheduling and respectful timing.</div>
      </div>
    </section>

    <div style="margin-top:18px">
      <a class="cta" href="{{PRIMARY_CTA_URL}}" id="finalCTA">Reserve a session</a>
    </div>

  </main>

  <footer>
    <div>Call us: <a href="tel:{{PHONE}}">{{PHONE}}</a> &nbsp; • &nbsp; Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
    <div style="margin-top:8px">Small-batch blends and considered sessions • local to {{CITY}}, {{STATE}}</div>
  </footer>

  <script>
    // Pricing comparator animation
    function animateNumber(el, start, end, duration){
      const startTime = performance.now();
      requestAnimationFrame(function tick(now){
        const progress = Math.min((now - startTime)/duration,1);
        const val = Math.round(start + (end - start)*progress);
        el.textContent = '$' + val;
        if(progress < 1) requestAnimationFrame(tick);
      });
    }
    document.addEventListener('DOMContentLoaded',function(){
      const monthlyBtn = document.getElementById('monthlyBtn');
      const packageBtn = document.getElementById('packageBtn');
      const priceEls = Array.from(document.querySelectorAll('.priceValue'));

      function setMode(mode){
        [monthlyBtn,packageBtn].forEach(b=>b.classList.toggle('active', b.id.startsWith(mode)));
        priceEls.forEach(el=>{
          const start = parseInt(el.textContent.replace(/[^0-9]/g,''),10) || 0;
          const end = parseInt(el.getAttribute('data-' + (mode==='monthly'? 'monthly' : 'package')) ,10);
          animateNumber(el, start, end, 500);
        });
      }

      monthlyBtn.addEventListener('click',()=>setMode('monthly'));
      packageBtn.addEventListener('click',()=>setMode('package'));

      // Initial set
      priceEls.forEach(el=>el.textContent = '$' + el.getAttribute('data-monthly'));

      // Mood-to-method
      const moodBtns = document.querySelectorAll('.moodBtn');
      const recommendText = document.getElementById('recommendText');
      const moodCTA = document.getElementById('moodCTA');
      const finalCTA = document.getElementById('finalCTA');

      const moods = {
        stressed: {label:'Short grounding',desc:'A 20–30 minute grounding protocol with a focused inhale/exhale practice and a calming blend that may support stress relief. Includes simple at-home tools.',cta:'Start a grounding consult'},
        sleep:{label:'Evening ritual',desc:'A gentle pre-sleep routine with sleep-safe dilutions and a warm-down blend that may support quieter nights.',cta:'Get the sleep plan'},
        fog:{label:'Clarity focus',desc:'A clarity-focused session with an uplifting amber-citrus blend and short breathwork to help orient attention.',cta:'Book clarity session'},
        lifted:{label:'Energy nudge',desc:'An energizing micro-practice and a bright, circulation-supporting blend that may lift low energy.',cta:'Try an energy nudge'},
        celebrate:{label:'Lift & notice',desc:'A celebratory blend and a short sensory ritual to mark small wins and invite noticing.',cta:'Create a ritual'}
      };

      moodBtns.forEach(btn=>btn.addEventListener('click',function(){
        moodBtns.forEach(b=>b.classList.remove('selected'));
        this.classList.add('selected');
        const key = this.getAttribute('data-key');
        const m = moods[key];
        recommendText.textContent = m.label + ' — ' + m.desc;
        moodCTA.textContent = m.cta;
        moodCTA.href = '{{PRIMARY_CTA_URL}}' + '?intent=' + encodeURIComponent(key);
        finalCTA.textContent = m.cta;
      }));

    });
  </script>
</body>
</html>"} 
