  <script>
    // Pricing comparator for shop
    function animateNumber(el,start,end,duration){
      const s = performance.now();
      requestAnimationFrame(function fn(now){
        const p = Math.min((now - s)/duration,1);
        el.textContent = Math.round(start + (end - start)*p);
        if(p < 1) requestAnimationFrame(fn);
      });
    }

    document.addEventListener('DOMContentLoaded',function(){
      const singleView = document.getElementById('singleView');
      const subView = document.getElementById('subView');
      const products = Array.from(document.querySelectorAll('.product'));
      const cartCount = document.getElementById('cartCount');
      let count = 0;

      function setMode(mode){
        singleView.classList.toggle('active', mode==='single');
        subView.classList.toggle('active', mode==='sub');
        products.forEach(prod=>{
          const one = parseInt(prod.getAttribute('data-one'),10);
          const sub = parseInt(prod.getAttribute('data-sub'),10);
          const span = prod.querySelector('.num');
          const start = parseInt(span.textContent,10) || one;
          const end = mode==='single'? one : sub;
          animateNumber(span,start,end,400);
        });
      }

      singleView.addEventListener('click',()=>setMode('single'));
      subView.addEventListener('click',()=>setMode('sub'));

      // Add to cart simulation
      document.querySelectorAll('.add').forEach(btn=>btn.addEventListener('click',function(e){
        e.preventDefault();
        count += 1;
        cartCount.textContent = count;
        // tiny pulse
        const el = document.getElementById('cartBar');
        el.animate([{transform:'scale(1)'},{transform:'scale(1.06)'},{transform:'scale(1)'}],{duration:300});
        // redirect to booking or CTA path
        const href = this.getAttribute('href');
        setTimeout(()=>{ window.location.href = href; },400);
      }));

      // initial prices set
      products.forEach(p=>{
        const n = p.querySelector('.num');
        n.textContent = p.getAttribute('data-one');
      });

    });
  </script>
